// String rules for well-known textual formats: email, hostname, address,
// ip/ipv4/ipv6 (and prefix-length variants), uri/uri_ref, uuid/tuuid/ulid,
// host_and_port, protobuf_fqn / protobuf_dot_fqn.
//
